nextflow_process {
    name "Test Process KRAKEN2_KRAKEN2"
    script "../main.nf"
    process "KRAKEN2_KRAKEN2"
    tag "modules"
    tag "modules_nfcore"
    tag "kraken2"
    tag "kraken2/kraken2"

    test("sarscov2 illumina single end [fastq]") {
        def db
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/kraken2.tar.gz').resolve('kraken2')
        }

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ], // meta map
                    [ file(
                        params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_1.fastq.gz",
                        checkIfExists: true
                    )]
                ]
                input[1] = file('${db}')
                input[2] = true
                input[3] = false
                """
            }
        }

        then {
            assertAll(
            { assert process.success },
            { assert snapshot(
                    process.out.report,
                    process.out.findAll { key, val -> key.startsWith("versions") },
                ).match()
            },
            { assert process.out.classified_reads_fastq.get(0).get(1) ==~ ".*/test.classified.fastq.gz" },
            { assert process.out.unclassified_reads_fastq.get(0).get(1) ==~ ".*/test.unclassified.fastq.gz" },
            )
        }
    }

    test("sarscov2 illumina paired end [fastq]") {
        def db
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/kraken2.tar.gz').resolve('kraken2')
        }

        when {
            params {
                outdir   = "$outputDir"
            }

            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(
                            params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_1.fastq.gz",
                            checkIfExists: true
                        ),
                        file(
                            params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_2.fastq.gz",
                            checkIfExists: true
                        )

                        ]
                    ]
                input[1] = file('${db}')
                input[2] = true
                input[3] = false
                """
            }
        }

        then {
            assertAll(
            { assert process.success },
            { assert snapshot(
                    process.out.report,
                    process.out.findAll { key, val -> key.startsWith("versions") },
                ).match()
            },
            { assert process.out.classified_reads_fastq.get(0).get(1).get(0)
                ==~ ".*/test.classified_1.fastq.gz" },
            { assert process.out.classified_reads_fastq.get(0).get(1).get(1)
                ==~ ".*/test.classified_2.fastq.gz" },
            { assert process.out.unclassified_reads_fastq.get(0).get(1).get(0)
                ==~ ".*/test.unclassified_1.fastq.gz" },
            { assert process.out.unclassified_reads_fastq.get(0).get(1).get(1)
                ==~ ".*/test.unclassified_2.fastq.gz" },
            )
        }
    }

