            db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/kraken2.tar.gz').resolve('kraken2')
        }

        when {
            params {
                outdir   = "$outputDir"
            }

            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ], // meta map
                    [ file(
                        params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_1.fastq.gz",
                        checkIfExists: true
                    )]
                ]
                input[1] = file('${db}')
                input[2] = false
                input[3] = true
                """
            }
        }

        then {
            assertAll(
            { assert process.success },
            { assert snapshot(
                    process.out.report,
                    process.out.findAll { key, val -> key.startsWith("versions") },
                    process.out.classified_reads_assignment,
                ).match()
            },
            )
        }
    }

